repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('upper', 24), ('lower', 7), ('upper', 49), ('river', 43), ('river', 58)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.distinct.py:
"""Distinct field values among harvests."""


def new_fields(harvests, seen=set()):
    """Return each field the first time it appears among the harvests, in order. field values already in `seen` are left out."""
    out = []
    for x in harvests:
        if x.field not in seen:
            seen.add(x.field)
            out.append(x.field)
    return out


def count_fields(harvests):
    """Return how many distinct field values the harvests have."""
    return len(set(x.field for x in harvests))


def describe_harvest(harvest):
    """Return a one-line description of a harvest."""
    return "%s: %s" % (harvest.field, harvest.kilos)


def field_names(harvests):
    """Return the distinct field values, in first-seen order."""
    names = []
    for x in harvests:
        if x.field not in names:
            names.append(x.field)
    return names
